#nullable enable // autogenerated  

using MVZ2.GameContent.Contraptions;   // GridFire  
using MVZ2.GameContent.Effects;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Projectiles
{
    [AutoEntityBehaviourDefinition(VanillaProjectileNames.Molotov)]
    public class Molotov : EntityBehaviourDefinition
    {
        public Molotov(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            // 与 Grenade/Flashbang 一致：飞行途中不与任何实体碰撞，仅靠落地判定触发  
            entity.CollisionMaskHostile = 0;
            entity.CollisionMaskFriendly = 0;
        }
        public override void Update(Entity projectile)
        {
            base.Update(projectile);
            if (projectile.GetRelativeY() <= 0)   // 落地  
            {
                Ignite(projectile);
                projectile.Remove();
            }
        }
        private void Ignite(Entity projectile)
        {
            var level = projectile.Level;
            var center = projectile.GetCenter();
            center.y = level.GetGroundY(center.x, center.z);

            // 落地火焰特效  
            level.Spawn(VanillaEffectID.fireburn, center, null);

            // —— 在落点周围 3×3 格生成火焰地格（grid_fire）——  
            int column = level.GetColumn(center.x);
            int lane = level.GetLane(center.z);
            var spawnParam = projectile.GetSpawnParams();
            for (int x = column - 1; x <= column + 1; x++)
            {
                for (int y = lane - 1; y <= lane + 1; y++)
                {
                    var grid = level.GetGrid(x, y);
                    if (grid == null)
                        continue;
                    GridFire.Spawn(grid, projectile, spawnParam); // 只在陆地格生效、同格不重复  
                }
            }

            // —— 让范围内的敌人燃烧（标准 BurningBuff，视觉同暗影细胞自燃的 fireburn）——  
            float radius = 3 * 80 * 0.5f; // 约 3×3 格，格宽约 80  
            foreach (var target in level.FindEntities(e =>
                e.IsVulnerableEntity() && projectile.IsHostile(e)))
            {
                if ((target.GetCenter() - center).magnitude > radius)
                    continue;
                target.InflictBurning(BURN_FRAMES, null, BURN_DAMAGE_PER_HIT);
            }
            projectile.PlaySound(VanillaSoundID.fireCharge);
        }
        public const int BURN_FRAMES = 150;            // 燃烧持续帧数（≈5s）  
        public const float BURN_DAMAGE_PER_HIT = 50f;  // BurningBuff 每秒跳一次的伤害  
    }
}
